fn solve(x: i32) -> i32 {
    // Extract the digit that x consists of
    // For a boring number, all digits are the same, so we can just look at the first digit
    let d = (x.to_string().chars().next().unwrap().to_digit(10).unwrap()) as i32;
    
    // Determine the length k (how many times the digit is repeated)
    let k = x.to_string().len() as i32;
    
    // Calculate total button presses:
    // 1. For all complete digits before d: (d-1) * 10
    //    (each digit 1 through d-1 contributes 1+2+3+4 = 10 presses)
    // 2. For digit d up to length k: 1+2+...+k = k*(k+1)/2
    
    let complete_digits = (d - 1) * 10;
    let current_digit = k * (k + 1) / 2;
    
    complete_digits + current_digit
}